function loadWorkflow(id){const w=workflowCatalog[id];if(!w)return;state.workflow=id;state.newWorkflow=false;state.items={};state.skips=[...w.skips];stages.splice(0,stages.length,...w.stages.map(x=>({id:x[0],name:x[1],days:x[2],count:x[3]})));branches.splice(0,branches.length,...w.branches.map(x=>({id:x[0],name:x[1],meta:x[2],desc:x[3],conditions:x[4]})));Object.entries(w.items).forEach(([k,v])=>state.items[k]=v.map((x,i)=>({id:k+'-'+i,type:x[0],title:x[1],meta:x[2]})));extras={...w.extras};}
function startNewWorkflow(){state.workflow='new';state.newWorkflow=true;state.screen='editor';state.step='base';state.view='canvas';state.layer='process';state.items={};state.skips=[];state.newRules=0;state.newRoles=[];state.audienceDepartments=false;state.audiencePositions=false;state.goalsOpen=false;state.ktOpen=false;state.paletteOpen=false;state.focus=null;state.editBranchId=null;state.editStageId=null;state.stageModalOpen=false;state.participantModalOpen=false;state.scenarioModal=null;state.assignmentModalOpen=false;state.mappingModal=null;state.newGoalScenario=false;state.newKtScenario=false;state.unmatchedImport=0;state.replaceItem=null;stages.splice(0);branches.splice(0);extras={};render()}
function currentWorkflow(){return workflowCatalog[state.workflow]||{name:'Новый workflow',short:'Черновик',stats:['0 веток','0 элементов','0 КТ']}}
