function hub(){return `<div class="hub"><header class="topbar"><div class="brand"><span class="brand-mark">S</span>Skillaz Start</div><div class="crumb">Workflow адаптации</div><div class="topbar-spacer"></div><button class="btn">Справка</button></header><main class="hub-main"><div class="hub-head"><div><h1>Workflow адаптации</h1><p class="muted">Заполненные обезличенные примеры для массовых и руководящих ролей.</p></div><button class="btn primary" data-action="new">＋ Новый workflow</button></div><div class="workflow-list"><article class="workflow-card featured"><span class="tag green">Демо · массовые роли</span><h3>Единый workflow логистической сети</h3><p>Доставка, склад и клиентские офисы: общий контур, подключаемые модули и допуски.</p><div class="workflow-stats"><div><b>4</b><small>ветки</small></div><div><b>96</b><small>элементов</small></div><div><b>2</b><small>сценария КТ</small></div></div><button class="btn primary" data-workflow="courier">Открыть канву</button> <button class="btn" data-workflow-tour="courier">Вся сборка</button></article><article class="workflow-card"><span class="tag purple">Демо · 90 дней</span><h3>Стажировка руководителей клиентского офиса</h3><p>Обучение сотрудника и задачи руководителя, наставника и экспертов в одной временной линии.</p><div class="workflow-stats"><div><b>3</b><small>ветки</small></div><div><b>82</b><small>элемента</small></div><div><b>2</b><small>сценария КТ</small></div></div><button class="btn primary" data-workflow="manager">Открыть канву</button></article><article class="workflow-card"><span class="tag">Создание</span><h3>Новый workflow с нуля</h3><p>Настройте основу, участников, ветки, этапы, цели и контрольные точки.</p><div class="workflow-stats"><div><b>4</b><small>шага</small></div><div><b>∞</b><small>веток</small></div><div><b>9</b><small>типов элементов</small></div></div><button class="btn" data-action="new">Создать</button></article></div></main></div>`}
function editor(){const w=currentWorkflow();return `<header class="topbar"><button class="btn ghost" data-action="home">←</button><div class="brand"><span class="brand-mark">S</span>Skillaz Start</div><div class="titleblock"><b>${state.newWorkflow?'Новый workflow':w.name}</b><small>${state.newWorkflow?'Пустой черновик · изменения сохраняются в прототипе':w.short+' · версия 4 · сохранено минуту назад'}</small></div><div class="topbar-spacer"></div><button class="btn">Предпросмотр</button><button class="btn primary" data-action="openPublish">Опубликовать</button></header><div class="shell">${steps()}<main class="main">${state.step==='canvas'?canvasPage():settingsPage()}</main></div>${drawer()}${bulkModal()}${branchModal()}${stageModal()}${importModal()}${publishModal()}<div id="toast" class="toast hidden"></div>`}
function steps(){const data=[['base','Основа','Аудитория и правила'],['participants','Участники','Роли и автоподбор'],['canvas','Канва','Ветки, этапы и элементы'],['settings','Настройки','Уведомления и публикация']];return `<nav class="stepbar"><span class="setup-label">Настройка workflow</span>${data.map((s,i)=>`<button class="step ${state.step===s[0]?'active':''}" data-step="${s[0]}"><span class="step-num">${i+1}</span><span><b>${s[1]}</b><small>${s[2]}</small></span></button>`).join('')}</nav>`}
function settingsPage(){if(state.step==='participants')return participantsPageV2();if(state.step==='settings')return finalPage();return basePageV2()}
function basePage(){return `<div class="editor-toolbar"><b>Основа workflow</b><div class="topbar-spacer"></div><span class="tag green">Настроено</span></div><div class="page"><div class="page-card wide-card"><div class="settings-title"><div><h1>Кого и когда включать в workflow</h1><p class="muted">Аудитория ограничивает доступные значения, а отдельные правила определяют момент назначения.</p></div><button class="btn" data-view="verify">Проверить на сотрудниках</button></div><div class="settings-grid"><section class="setting"><b>Подразделения workflow</b><p class="muted">Древовидный множественный выбор без условий</p><div class="chips"><span class="tag blue">Логистическая сеть</span><span class="tag blue">Складская логистика + дочерние</span><span class="tag blue">Клиентские офисы + дочерние</span></div><button class="btn small" style="margin-top:10px">Изменить структуру</button></section><section class="setting"><b>Должности workflow</b><p class="muted">Несколько групп и отдельных должностей</p><div class="chips"><span class="tag blue">Доставка</span><span class="tag blue">Складские роли</span><span class="tag blue">Клиентский сервис</span></div><button class="btn small" style="margin-top:10px">Изменить выбор</button></section><section class="setting wide"><b>Период адаптации</b><div class="period-row"><label>Длительность <span><input value="90"> дней</span></label><label>Точка отсчета <select><option>Дата выхода на работу</option></select></label><label>Календарь <select><option>Рабочий график сотрудника</option></select></label></div></section><section class="setting wide"><div class="section-head"><div><b>Правила назначения</b><p class="muted">Можно создать несколько правил. Выполнение проверяется по актуальным данным мастер-системы.</p></div><button class="btn">＋ Добавить правило</button></div><div class="assignment-rules"><article><span class="rule-number">1</span><div><small>КОГДА</small><b>Создан новый сотрудник или кандидат</b><p>За 5 дней до даты выхода</p></div><div><small>ЕСЛИ</small><b>Подразделение: клиентские офисы · должность: специалист</b><p>Адрес заполнен · дата найма есть</p></div><div><small>ТОГДА</small><b>Назначить workflow</b><p>Не создавать повторный план</p></div><button class="btn icon-only">•••</button></article><article><span class="rule-number">2</span><div><small>КОГДА</small><b>Изменилась должность сотрудника</b><p>Проверять каждый час</p></div><div><small>ЕСЛИ</small><b>Новая должность: кладовщик или сортировщик</b><p>Стаж в должности меньше 5 дней</p></div><div><small>ТОГДА</small><b>Назначить ветку склада</b><p>Сохранить ручных участников</p></div><button class="btn icon-only">•••</button></article><article><span class="rule-number">3</span><div><small>КОГДА</small><b>Возврат после длительного отсутствия</b><p>Проверять ежедневно в 09:15</p></div><div><small>ЕСЛИ</small><b>Перерыв более 180 дней</b><p>Статус сотрудника активный</p></div><div><small>ТОГДА</small><b>Назначить повторную адаптацию</b><p>Только после проверки администратором</p></div><button class="btn icon-only">•••</button></article></div><div class="rule-safety"><span>✓ Повторные планы исключены</span><span>✓ При ошибке участника план не назначается</span><span>✓ Ручное назначение остается доступным</span></div></section></div></div></div>`}
function basePageV2(){if(state.newWorkflow)return emptyBasePage();return basePage()
 .replace('ПВЗ + дочерние','Клиентские офисы + дочерние')
 .replace('Курьеры','Доставка')
 .replace('Кладовщики','Складские роли')
 .replace('Менеджеры ПВЗ','Клиентский сервис')
 .replace('</div><div class="settings-grid">','</div><section class="composition-model"><div><span class="tag green">Базовый слой</span><b>Общий корпоративный контур</b><small>Документы, безопасность, знакомство с компанией</small></div><i>＋</i><div><span class="tag blue">Формат</span><b>Склад / офис / торговая точка</b><small>Подключается по адресу и типу подразделения</small></div><i>＋</i><div><span class="tag purple">Профессия</span><b>Роль и функциональный блок</b><small>Курсы, практика, задачи и допуски</small></div><i>＋</i><div><span class="tag amber">Событие</span><b>Найм / перевод / возврат</b><small>Меняет состав и сроки без копии шаблона</small></div></section><div class="settings-grid">')}
function emptyBasePage(){const rules=Array.from({length:state.newRules},(_,i)=>`<article><span class="rule-number">${i+1}</span><div><small>КОГДА</small><select><option>Выберите событие</option><option>Создан новый сотрудник</option><option>Изменилась должность</option><option>Сотрудник вышел из отпуска</option></select><p>Настройте момент проверки</p></div><div><small>ЕСЛИ</small><button class="btn small">＋ Добавить условия</button><p>Подразделение, должность, адрес, график и другие данные</p></div><div><small>ТОГДА</small><b>Назначить этот workflow</b><p>Без повторного активного плана</p></div><button class="btn icon-only">•••</button></article>`).join('');return `<div class="editor-toolbar"><b>Основа workflow</b><div class="topbar-spacer"></div><span class="tag">Не настроено</span></div><div class="page"><div class="page-card wide-card"><div class="settings-title"><div><h1>Кого и когда включать в workflow</h1><p class="muted">Сначала задайте общую аудиторию, затем добавьте правила автоматического назначения.</p></div></div><div class="settings-grid"><section class="setting"><b>Подразделения workflow</b><p class="muted">Древовидный множественный выбор без условий</p>${state.audienceDepartments?'<div class="chips"><span class="tag blue">Выбранные подразделения</span><span class="tag blue">＋ дочерние</span></div>':'<div class="blank-field">Подразделения еще не выбраны</div>'}<button class="btn small" style="margin-top:10px" data-action="selectDepartments">${state.audienceDepartments?'Изменить':'Выбрать подразделения'}</button></section><section class="setting"><b>Должности workflow</b><p class="muted">Можно выбрать группы и отдельные должности</p>${state.audiencePositions?'<div class="chips"><span class="tag blue">Выбранные должности</span></div>':'<div class="blank-field">Должности еще не выбраны</div>'}<button class="btn small" style="margin-top:10px" data-action="selectPositions">${state.audiencePositions?'Изменить':'Выбрать должности'}</button></section><section class="setting wide"><b>Период адаптации</b><div class="period-row"><label>Длительность <span><input type="number" min="1" placeholder="Например, 90"> дней</span></label><label>Точка отсчета <select><option>Выберите событие</option><option>Дата выхода на работу</option><option>Дата назначения плана</option></select></label><label>Календарь <select><option>Выберите календарь</option><option>Календарные дни</option><option>Рабочий график сотрудника</option></select></label></div></section><section class="setting wide"><div class="section-head"><div><b>Правила назначения</b><p class="muted">Правил может быть несколько. Ручное назначение останется доступным независимо от них.</p></div><button class="btn" data-action="addRule">＋ Добавить правило</button></div>${rules?`<div class="assignment-rules">${rules}</div>`:'<div class="empty-setting"><b>Автоматических правил пока нет</b><span>Добавьте первое правило или оставьте workflow только для ручного назначения.</span></div>'}</section></div><div class="wizard-next"><button class="btn primary" data-step="participants">Продолжить к участникам →</button></div></div></div>`}
function emptyParticipantsPage(){return `<div class="editor-toolbar"><b>Участники плана</b><div class="topbar-spacer"></div><span class="tag">${state.newRoles.length} бизнес-ролей</span></div><div class="page participants-page"><div class="page-card wide-card"><div class="section-head"><div><h1>Кто участвует в процессе</h1><p class="muted">Системные роли доступны сразу. Бизнес-роли добавляются без ограничения и позже связываются с задачами.</p></div><button class="btn primary" data-action="addRole">＋ Добавить бизнес-роль</button></div><h2 class="role-section-title">Системные роли</h2><div class="system-roles"><section><span class="tag blue">Системная роль</span><h3>Адаптируемый</h3><p>Определяется назначением плана</p></section><section><span class="tag blue">Системная роль</span><h3>Руководитель</h3><p>Административный, функциональный или ручной выбор</p></section></div><h2 class="role-section-title">Бизнес-роли</h2>${state.newRoles.length?`<div class="business-role-table"><div class="role-row head"><span>Роль</span><span>Охват</span><span>Использование</span><span>Подбор</span></div>${state.newRoles.map((r,i)=>`<div class="role-row"><span><input data-new-role="${i}" value="${r.name}" aria-label="Название роли"></span><span><select data-new-role-scope="${i}"><option>Свое подразделение</option><option>Подразделение и дочерние</option><option>Вся организация</option></select></span><span>Будет задано на канве</span><span><span class="tag amber">Настроить</span></span></div>`).join('')}</div>`:'<div class="empty-setting"><b>Бизнес-роли еще не добавлены</b><span>Например: наставник, HRBP, эксперт по безопасности или тренер.</span></div>'}<div class="wizard-next"><button class="btn primary" data-step="canvas">Перейти к пустой канве →</button></div></div></div>`}
function participantsPage(){const roles=[
 ['Наставник склада','Свое подразделение','Кладовщик, сортировщик'],
 ['Наставник доставки','Подразделение и дочерние','Курьер, курьер-водитель'],
 ['Руководитель ПВЗ','Свое подразделение','Менеджер ПВЗ'],
 ['Региональный менеджер','Подразделение и дочерние','Руководящие роли'],
 ['Тренер по продукту','Вся организация','Обучение и допуски'],
 ['Эксперт по безопасности','Вся организация','Обязательные проверки'],
 ['HRBP / куратор','Подразделение и дочерние','Контрольные точки'],
 ['Первый наставник МП','Свое подразделение','Стажеры и МП']
 ];return `<div class="editor-toolbar"><b>Участники плана</b><div class="topbar-spacer"></div><span class="tag green">${roles.length+2} ролей · без лимита</span></div><div class="page participants-page"><div class="page-card wide-card"><div class="section-head"><div><h1>Роли, которые участвуют в процессе</h1><p class="muted">Здесь задаются роли, а не конкретные люди. При назначении система найдет сотрудника по структуре и охвату; администратор сможет заменить его вручную.</p></div><button class="btn primary">＋ Добавить бизнес-роль</button></div><div class="role-principle"><b>Как работает подбор</b><span>Роль в workflow</span><i>→</i><span>Подходящий помощник из справочника</span><i>→</i><span>Проверка доступности для подразделения</span><i>→</i><span>Конкретный участник плана</span></div><h2 class="role-section-title">Системные роли</h2><div class="system-roles"><section><span class="tag blue">Системная роль</span><h3>Адаптируемый</h3><p>Сотрудник, которому назначается план</p><small>Определяется самим назначением</small></section><section><span class="tag blue">Системная роль</span><h3>Руководитель</h3><p>Административный или функциональный по структуре</p><small>Fallback: ручной выбор любого сотрудника</small></section></div><div class="role-section-head"><div><h2>Бизнес-роли</h2><p class="muted">Набор не ограничен. Одна роль может выполнять задачи только в выбранных ветках.</p></div><div class="role-filter"><input placeholder="Найти роль"><button class="btn">Все охваты</button></div></div><div class="business-role-table"><div class="role-row head"><span>Роль</span><span>Охват помощника</span><span>Используется в ветках</span><span>Подбор</span></div>${roles.map((r,i)=>`<button class="role-row"><span><b>${r[0]}</b><small>${i%3===0?'Задачи и контрольные точки':'Задачи этапов'}</small></span><span>${r[1]}</span><span>${r[2]}</span><span><span class="tag ${i===7?'amber':'green'}">${i===7?'Ручной fallback':'Автоподбор'}</span> ›</span></button>`).join('')}</div><div class="role-safety"><b>Перед публикацией проверим участников</b><span>Покажем, для каких сотрудников не найден помощник или найдено несколько кандидатов. Такие планы не запустятся молча.</span><button class="btn" data-view="verify">Проверить на сотрудниках</button></div></div></div>`}
function finalPage(){return `<div class="editor-toolbar"><b>Настройки workflow</b><div class="topbar-spacer"></div><span class="tag green">Проверки пройдены</span></div><div class="page"><div class="page-card wide-card"><div class="settings-title"><div><h1>Публикация, версии и сопровождение</h1><p class="muted">Изменения не попадают в активные планы без явного решения администратора.</p></div><button class="btn" data-action="openImport">⇧ Импортировать текущие шаблоны</button></div><div class="settings-grid"><section class="setting"><b>Режим назначения</b><p>Автоматически по правилам и вручную из редактора плана</p><div class="chips"><span class="tag green">Оба режима</span></div></section><section class="setting"><b>Текущая версия</b><p><b>Версия 4</b> · черновик от 19 сентября</p><div class="chips"><span class="tag">Версия 3 опубликована</span><button class="btn small">Сравнить</button></div></section><section class="setting wide"><b>К каким планам применять изменения</b><div class="radio-stack"><label><input type="radio" name="impact" checked> Только к новым назначениям <small>Безопасный режим по умолчанию</small></label><label><input type="radio" name="impact"> Обновить незавершенные планы <small>1 248 планов · перед публикацией покажем изменения</small></label><label><input type="radio" name="impact"> Выбрать планы вручную <small>Фильтр по ветке, подразделению и статусу</small></label></div></section><section class="setting wide"><b>Уведомления плана</b>${['План назначен','Скоро начнется план','Приближается окончание','Изменились даты','Изменился участник'].map(x=>`<div class="toggle-row"><span>${x}</span><span class="switch on"></span></div>`).join('')}</section><section class="setting wide"><b>Последние запуски</b><div class="run-table"><span>Сегодня, 09:15</span><b>Назначение новых сотрудников</b><span class="tag green">24 назначено</span><span>3 пропущено</span><span>Вчера, 18:10</span><b>Повторная проверка данных</b><span class="tag amber">2 ошибки ролей</span><button class="btn small">Открыть журнал</button></div></section></div></div></div>`}
function canvasPage(){const w=currentWorkflow(),itemCount=Object.values(state.items).reduce((n,a)=>n+a.length,0),stats=state.newWorkflow?[`${branches.length} веток`,`${itemCount} элементов`,'0 сценариев КТ']:w.stats;return `<div class="editor-toolbar"><div class="titleblock"><b>${state.view==='canvas'?'Канва workflow':'Проверка перед запуском'}</b><small>${stats.join(' · ')} · ${stages.length} этапов</small></div><div class="view-tabs"><button data-view="canvas" class="${state.view==='canvas'?'active':''}">Конструктор</button><button data-view="verify" class="${state.view==='verify'?'active':''}">Проверка веток${state.newWorkflow?'':' <span class="issue-badge">3</span>'}</button></div><div class="topbar-spacer"></div><button class="btn" data-action="openImport">⇧ Импорт</button>${state.newWorkflow?'':'<button class="btn" data-action="tour">▶ Показать создание</button>'}<button class="btn primary" data-view="verify">Проверить workflow</button></div>${state.view==='verify'?verificationPage():canvasWorkspace()}`}
function canvasWorkspace(){const ready=stages.length&&branches.length;return `<div class="workspace ${state.compact?'compact-mode':''} ${state.differences?'differences-mode':''}">${palette()}<section class="canvas-shell"><div class="canvas-tools"><button class="btn primary" data-action="togglePalette" ${ready?'':'disabled'}>＋ Добавить элементы</button><button class="btn" data-action="addBranch">⑂ Ветка</button><button class="btn" data-action="addStage">▤ Этап</button><div class="layer-switch"><button data-layer="process" class="${state.layer==='process'?'active':''}">Процесс</button><button data-layer="goals" class="${state.layer==='goals'?'active':''}">Цели</button><button data-layer="checkpoints" class="${state.layer==='checkpoints'?'active':''}">КТ</button><button data-layer="roles" class="${state.layer==='roles'?'active':''}">Исполнители</button></div><input class="canvas-search" value="${state.query}" placeholder="Найти на канве" data-canvas-search><button class="btn small ${state.differences?'active-tool':''}" data-action="differences">Только отличия</button><button class="btn small ${state.compact?'active-tool':''}" data-action="compact">Компактно</button><div class="spacer"></div><button class="btn small" data-action="fit">Вписать</button><button class="btn icon-only small" data-action="zoomout">−</button><span id="zoomValue">${Math.round(state.zoom*100)}%</span><button class="btn icon-only small" data-action="zoomin">＋</button></div><div class="canvas-viewport" id="viewport"><div class="canvas-surface" id="surface">${ready?`<div class="canvas-note"><span class="icon">i</span><div><b>Каждый сотрудник получает общий контур и одну или несколько подходящих веток</b><small class="muted">Приоритеты, пересечения и ветка «Иначе» проверяются до публикации.</small></div></div>${scenarioRail()}${flowGrid()}${checkpointRail()}`:emptyCanvasState()}<svg class="connections" id="edges"></svg>${ready?'<div class="minimap"><div class="mini-grid"></div></div>':''}</div></div></section></div>`}
function emptyCanvasState(){const stageReady=stages.length>0;return `<section class="empty-canvas"><span class="empty-canvas-icon">＋</span><h2>${stageReady?'Теперь добавьте ветки плана':'Сначала создайте этапы'}</h2><p>${stageReady?'Ветка объединяет одну или несколько должностей и подразделений, для которых собирается один вариант плана.':'Этапы задают общую временную шкалу: название, срок, последовательность и обязательность.'}</p><div class="empty-canvas-progress"><span class="${stageReady?'done':''}">${stageReady?'✓':'1'} Этапы</span><i>→</i><span class="${branches.length?'done':''}">${branches.length?'✓':'2'} Ветки</span><i>→</i><span>3 Элементы</span></div><div><button class="btn primary" data-action="${stageReady?'addBranch':'addStage'}">＋ ${stageReady?'Создать ветку':'Создать этап'}</button>${stageReady?'<button class="btn" data-action="addStage">＋ Ещё этап</button>':''}<button class="btn" data-action="openImport">⇧ Импортировать шаблон</button></div></section>`}
