 $$('[data-action="openAssignment"]').forEach(x=>x.onclick=()=>{state.assignmentModalOpen=true;render()});
 $$('[data-action="closeAssignment"]').forEach(x=>x.onclick=()=>{state.assignmentModalOpen=false;render()});
 $$('[data-action="saveAssignment"]').forEach(x=>x.onclick=()=>{state.assignmentModalOpen=false;render();toast('Правило назначения добавлено')});
 $$('[data-new-role]').forEach(x=>x.oninput=e=>{state.newRoles[Number(x.dataset.newRole)].name=e.target.value});
 $$('[data-new-role-scope]').forEach(x=>x.onchange=e=>{state.newRoles[Number(x.dataset.newRoleScope)].scope=e.target.value});
 $$('[data-action="addBranch"]').forEach(x=>x.onclick=()=>{state.editBranchId=null;$('#branchName').value='Новая ветка';$('#branchModal').hidden=false});
 $$('[data-branch-edit]').forEach(x=>x.onclick=e=>{if(e.target.closest('.branch-edit')){state.editBranchId=x.dataset.branchEdit;$('#branchName').value=branches.find(b=>b.id===x.dataset.branchEdit)?.name||'Ветка';$('#branchModal').hidden=false}});
 $$('[data-action="closeBranch"]').forEach(x=>x.onclick=()=>$('#branchModal').hidden=true);
 $$('[data-action="saveBranch"]').forEach(x=>x.onclick=()=>{const name=$('#branchName').value.trim()||'Новая ветка';if(state.editBranchId){const branch=branches.find(b=>b.id===state.editBranchId);if(branch)branch.name=name}else{const id='branch'+(branches.length+1);branches.push({id,name,meta:['Новая ветка','0 элементов'],desc:'Настройте аудиторию ветки',conditions:['Условия сохранены']})}state.editBranchId=null;$('#branchModal').hidden=true;render();toast('Ветка создана и добавлена на канву')});
 $$('[data-action="previewBranch"]').forEach(x=>x.onclick=()=>{$('#branchModal').hidden=true;state.view='verify';render();toast('Показана выборка для текущих условий')});
 $$('[data-action="openImport"]').forEach(x=>x.onclick=()=>{state.importOpen=true;state.importStep=1;render()});
 $$('[data-action="closeImport"]').forEach(x=>x.onclick=()=>{state.importOpen=false;render()});
 $$('[data-action="importMap"]').forEach(x=>x.onclick=()=>{state.importStep=2;render()});
 $$('[data-action="importBack"]').forEach(x=>x.onclick=()=>{state.importStep=1;render()});
 $$('[data-action="applyImport"]').forEach(x=>x.onclick=()=>{state.importOpen=false;state.view='canvas';state.unmatchedImport=3;render();toast('31 элемент размещён, 3 ждут решения на канве')});
 $$('[data-import-item]').forEach(x=>x.ondragstart=e=>{e.dataTransfer.setData('text/plain',x.innerHTML);x.classList.add('dragging')});
 $$('[data-import-target]').forEach(x=>{
  x.ondragover=e=>{e.preventDefault();x.classList.add('dragover')};
  x.ondragleave=()=>x.classList.remove('dragover');
  x.ondrop=e=>{
   e.preventDefault();x.classList.remove('dragover');
   const html=e.dataTransfer.getData('text/plain');
   const card=document.createElement('article');card.className='placed-import-item';card.innerHTML=html+'<em>Размещено вручную</em>';
   x.append(card);$('.unmatched-items .dragging')?.remove();
   const remaining=$$('[data-import-item]').length;
   const badge=$('.unmatched-head .tag.amber');if(badge)badge.textContent=`Нужно решение · ${remaining}`;
   toast('Элемент привязан к этапу вручную');
  }
 });
 $$('[data-action="openPublish"]').forEach(x=>x.onclick=()=>{state.publishOpen=true;render()});
 $$('[data-action="closePublish"]').forEach(x=>x.onclick=()=>{state.publishOpen=false;render()});
