 $$('[data-action="addStage"]').forEach(x=>x.onclick=()=>{const n=stages.length+1,id='stage'+Date.now();stages.push({id,name:'Новый этап '+n,days:'Срок не задан',count:0});state.editStageId=id;state.stageModalOpen=true;render()});
 $$('[data-action="closeStage"]').forEach(x=>x.onclick=()=>{state.stageModalOpen=false;render()});
 $$('[data-action="saveStage"]').forEach(x=>x.onclick=()=>{const s=stages.find(v=>v.id===state.editStageId);if(s){s.name=$('#stageName').value.trim()||s.name;s.days=$('#stageDays').value.trim()||'Срок не задан'}state.stageModalOpen=false;render();toast('Этап добавлен на канву')});
 $$('[data-action="zoomin"]').forEach(x=>x.onclick=()=>{state.zoom=Math.min(1.1,state.zoom+.1);applyZoom()});
 $$('[data-action="zoomout"]').forEach(x=>x.onclick=()=>{state.zoom=Math.max(.45,state.zoom-.1);applyZoom()});
 $$('[data-action="fit"]').forEach(x=>x.onclick=()=>{state.zoom=.62;applyZoom();$('#viewport').scrollTo({left:0,top:0,behavior:'smooth'})});
 $$('[data-focus]').forEach(x=>x.onclick=()=>{state.focus=state.focus===x.dataset.focus?null:x.dataset.focus;render()});
 $$('[data-item]').forEach(x=>{x.onclick=e=>{if(!e.target.closest('.card-actions'))openDrawer(x)};x.ondragstart=e=>e.dataTransfer.setData('text/plain',JSON.stringify({existing:true,id:x.dataset.item,source:x.dataset.sourceCell}))});
 $$('[data-replace-item]').forEach(x=>x.onclick=e=>{e.stopPropagation();const cell=x.dataset.replaceCell,item=(state.items[cell]||[]).find(i=>i.id===x.dataset.replaceItem);if(item){state.replaceItem={id:item.id,title:item.title,cell};render()}});
 $$('[data-action="closeReplace"]').forEach(x=>x.onclick=()=>{state.replaceItem=null;render()});
 $$('[data-action="applyReplace"]').forEach(x=>x.onclick=()=>{const next=$('#replacementTitle')?.value||'Обновлённый элемент',scope=$('input[name="replaceScope"]:checked')?.value||'all',old=state.replaceItem?.title,cell=state.replaceItem?.cell;if(scope==='all'){Object.values(state.items).forEach(list=>list.forEach(item=>{if(item.title===old)item.title=next}))}else{const item=(state.items[cell]||[]).find(i=>i.id===state.replaceItem?.id);if(item)item.title=next}state.replaceItem=null;render();toast(scope==='all'?'Элемент заменён во всех ветках':'Элемент заменён в текущем месте')});
 $$('[data-copy-item]').forEach(x=>x.onclick=e=>{e.stopPropagation();const list=state.items[x.dataset.copyCell]||[],item=list.find(i=>i.id===x.dataset.copyItem);if(item){list.push({...item,id:item.id+'-copy-'+Date.now(),title:item.title+' — копия'});render();toast('Элемент скопирован в этом этапе')}});
 $$('[data-action="replaceFromDrawer"]').forEach(x=>x.onclick=()=>{if(state.drawerItem){state.replaceItem={...state.drawerItem};render()}});
