 $$('[data-action="bulk"]').forEach(x=>x.onclick=()=>$('#bulkModal').hidden=false);
 $$('[data-action="closeModal"]').forEach(x=>x.onclick=()=>$('#bulkModal').hidden=true);
 $$('[data-action="applyBulk"]').forEach(x=>x.onclick=()=>{const k=$('#bulkBranch').value+'-'+$('#bulkStage').value;state.items[k]=state.items[k]||[];state.items[k].push({id:k+'-'+Date.now(),type:'course',title:'Новый набор из каталога',meta:'3 выбранных элемента'});$('#bulkModal').hidden=true;render();toast('3 элемента добавлены в выбранную ветку')});
